__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"TERMOS",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"PRIVACIDADE",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"VERSAO_TERMO_AVALIACAO",{enumerable:!0,get:function(){return t}}),e.termoAutorizacao=function(o,s){return[`Autorizo ${o} a publicar, de forma gratuita, a minha avalia\xe7\xe3o desta hospedagem: as estrelas, o texto da avalia\xe7\xe3o p\xfablica, as fotos que eu enviei e o nome "${s}".`,`A publica\xe7\xe3o pode ser feita nas redes sociais, no site e na p\xe1gina de avalia\xe7\xf5es de ${o}, para divulgar a hospedagem.`,'A mensagem direta que eu escrevi para a administradora n\xe3o faz parte desta autoriza\xe7\xe3o e nunca ser\xe1 publicada.','Meu sobrenome, telefone, e-mail, as datas exatas da estadia e o n\xfamero do apartamento n\xe3o ser\xe3o publicados.','Posso retirar esta autoriza\xe7\xe3o a qualquer momento pelo mesmo link da reserva. Depois disso, a avalia\xe7\xe3o deixa de ser usada em novas publica\xe7\xf5es.'].join('\n\n')};const o={chave:'termos',titulo:'Termos de uso',versao:'2026-10-29-rascunho',resumo:['O Maree Hub \xe9 uma plataforma da Atl\xe2ntico para guia do h\xf3spede, ordens de servi\xe7o e gest\xe3o de condom\xednio.','Voc\xea \xe9 respons\xe1vel pelas informa\xe7\xf5es que cadastra e pelo uso da sua conta e da sua equipe.','Os dados dos h\xf3spedes pertencem \xe0 administradora, ao anfitri\xe3o ou ao condom\xednio que os cadastrou.'],secoes:[{titulo:'1. O servi\xe7o',texto:'O Maree Hub oferece m\xf3dulos de guia da estadia, OS de hospedagem, OS de condom\xednio e acesso ao condom\xednio. Cada m\xf3dulo pode ser contratado separadamente, conforme o plano escolhido.'},{titulo:'2. Sua conta',texto:'Mantenha seus dados de acesso em seguran\xe7a. Quem voc\xea convida para a equipe (t\xe9cnicos, camareiras, empresas de limpeza, recep\xe7\xe3o) usa o sistema sob a sua conta e a sua responsabilidade.'},{titulo:'3. Conte\xfado e dados',texto:'Voc\xea declara ter o direito de cadastrar as informa\xe7\xf5es inseridas (aptos, regras, fotos, dados de h\xf3spedes e fornecedores) e de us\xe1-las para as finalidades do servi\xe7o.'},{titulo:'4. Uso adequado',texto:'\xc9 proibido usar a plataforma para fins ilegais, enviar conte\xfado ofensivo ou tentar acessar dados de outras contas.'},{titulo:'5. Planos e cancelamento',texto:'Os planos, limites e pre\xe7os est\xe3o descritos na contrata\xe7\xe3o. Voc\xea pode cancelar a qualquer momento e exportar seus dados antes do encerramento da conta.'},{titulo:'6. Contato',texto:'D\xfavidas sobre estes termos podem ser enviadas pelo canal de suporte do aplicativo.'}]},s={chave:'privacidade',titulo:'Pol\xedtica de privacidade',versao:'2026-10-29-rascunho',resumo:['Coletamos s\xf3 o necess\xe1rio para o servi\xe7o funcionar.','Dados de h\xf3spedes s\xe3o tratados em nome da administradora, do anfitri\xe3o ou do condom\xednio (somos operadores).','Voc\xea pode pedir acesso, corre\xe7\xe3o ou exclus\xe3o dos seus dados pelo canal de privacidade.'],secoes:[{titulo:'1. Quem somos',texto:'O Maree Hub \xe9 uma solu\xe7\xe3o Atl\xe2ntico. Para os dados das contas de usu\xe1rios, somos controladores; para os dados de h\xf3spedes, moradores e visitantes, atuamos como operadores em nome do cliente (administradora, anfitri\xe3o ou condom\xednio).'},{titulo:'2. Que dados coletamos',texto:'Dados de conta (nome, e-mail, telefone), dados de uso do sistema e, conforme os m\xf3dulos usados pelo cliente, dados de reservas, ocorr\xeancias, vistorias e acesso ao condom\xednio.'},{titulo:'3. Para que usamos',texto:'Para prestar o servi\xe7o contratado, dar suporte, manter a seguran\xe7a e cumprir obriga\xe7\xf5es legais. N\xe3o vendemos dados nem os usamos para publicidade de terceiros.'},{titulo:'4. Por quanto tempo',texto:'Fotos e v\xeddeos por 6 meses, dados pessoais de h\xf3spedes por 6 meses ap\xf3s a estadia e registros de acesso por 6 meses, salvo prazo maior exigido por lei ou disputa em andamento.'},{titulo:'5. Onde ficam',texto:'Em servidores do nosso provedor de banco de dados, preferencialmente na regi\xe3o de S\xe3o Paulo. Fornecedores de tecnologia podem processar dados fora do Brasil, com as garantias da LGPD.'},{titulo:'6. Seus direitos',texto:'Acesso, corre\xe7\xe3o, exclus\xe3o, portabilidade e revoga\xe7\xe3o de consentimento, pelo canal de privacidade do aplicativo.'}]},t='2026-10-29-rascunho'},865,[]);
